"Medeo Telegram-ның, банктің не байланыс операторының ақауларынан туындаған кідірістерге жауап бермейді, бірақ оларды тез шешуге көмектеседі.":"Medeo не отвечает за задержки из-за сбоев Telegram, банка или оператора связи, но помогает быстро их устранить.",
"Medeo Басқару":"Medeo Управление",
"Medeo Басқару тек рұқсат тізіміндегі Telegram аккаунттарына ашылады. Аккаунтыңыз расталды.":"Medeo Управление открыто только для Telegram-аккаунтов из списка разрешённых. Ваш аккаунт подтверждён.",
"Medeo Мекеме":"Medeo Заведение",
"Medeo Мекеменің пакеттерін Сервисте орналастырады, сатады, төлемді қабылдайды, есепті жүргізеді және тиесілі соманы Мекемеге аударады. Қызметті клиентке Мекеме тікелей көрсетеді.":"Medeo размещает пакеты Заведения в Сервисе, продаёт их, принимает оплату, ведёт учёт и перечисляет причитающуюся сумму Заведению. Услугу клиенту оказывает непосредственно Заведение.",
"Medeo Пайдаланушыға пакетті сатып алуға, оны сақтауға, мекемеде қолдануға, ұзартуға және сыйлауға мүмкіндік береді; төлемді қабылдайды және есепті жүргізеді.":"Medeo даёт Пользователю возможность купить пакет, хранить его, использовать в заведении, продлевать и дарить; принимает оплату и ведёт учёт.",
"Medeo Сервистің үздіксіз жұмысына тырысады. Техникалық жұмыстар кезінде Сервис уақытша қолжетімсіз болуы мүмкін; бұл кезде пакеттердің мерзімі қажет болса ұзартылады.":"Medeo стремится к бесперебойной работе Сервиса. Во время технических работ Сервис может быть временно недоступен; при необходимости срок пакетов продлевается.",
"Medeo агент ретінде әрекет ете ме (мекеменің атынан сатады) әлде өз атынан сатады ма — шарт құрылымы, ҚҚС және салық салдары осыған тәуелді. Ақша Medeo шотына түсіп, мекемеге қолданған сайын бөлінеді: бұл «төлем ұйымы» лицензиясын (ҚР «Төлемдер және төлем жүйелері туралы» Заңы) талап ете ме, әлде агенттік схема жеткілікті ме?":"Действует ли Medeo как агент (продаёт от имени заведения) или от своего имени — от этого зависят структура договора, НДС и налоговые последствия. Деньги поступают на счёт Medeo и распределяются заведению при каждом использовании: требует ли это лицензии «платёжной организации» (Закон РК «О платежах и платёжных системах») или достаточно агентской схемы?",
"Medeo атауы, логотипі, дизайны және бағдарламасы Medeo-ға тиесілі. Мекеменің атауы, суреттері мен сипаттамалары — мекемеге тиесілі.":"Название, логотип, дизайн и программа Medeo принадлежат Medeo. Название, фотографии и описания заведения принадлежат заведению.",
