"Medeo боты мерзім, сыйлық, тапсырыс және қауіпсіздік туралы хабарлайды. Жарнамалық хабарламаларды баптаудан өшіруге болады; төлем мен қауіпсіздік туралы хабарламалар өшпейді.":"Бот Medeo сообщает о сроках, подарках, заказах и безопасности. Рекламные уведомления можно отключить в настройках; уведомления об оплате и безопасности не отключаются.",
