"Medeo кассамен QR арқылы қазірдің өзінде жұмыс істейді. Жауабыңыз келесі қадамға көмектеседі: Medeo-ны касса бағдарламаңыздың ішіне қосамыз.":"Medeo уже работает с кассой через QR. Ваш ответ поможет на следующем шаге: мы встроим Medeo в вашу кассовую программу.",
"Medeo командасы 24 сағат ішінде қарайды. Бекітілген соң ұсыныс клиенттерге көрінеді, нәтижесін Telegram арқылы хабарлаймыз.":"Команда Medeo рассмотрит его в течение 24 часов. После утверждения предложение увидят клиенты, результат сообщим в Telegram.",
"Medeo командасы кейбір деректерді нақтылауды сұрады.":"Команда Medeo попросила уточнить некоторые данные.",
"Medeo комиссиясы":"Комиссия Medeo",
"Medeo офертаны өзгерте алады. Жаңа нұсқа Сервисте жарияланған сәттен күшіне енеді. Бұрын сатып алынған пакеттерге сатып алу сәтіндегі нұсқа қолданылады.":"Medeo может изменить оферту. Новая редакция вступает в силу с момента публикации в Сервисе. К ранее купленным пакетам применяется редакция, действовавшая на момент покупки.",
