"QR ішінде — біздің сервердегі қысқа сілтеме (/b/код). Ол бүгін Telegram мини аппқа, кейін қосымшаға бағыттайды — жапсырманы қайта басып шығару керек емес. Домен алынған соң STICKER_BASE_URL қойылады, ескі жапсырмалар да жұмыс істей береді.":"В QR — короткая ссылка на наш сервер (/b/код). Сегодня она ведёт в мини-приложение Telegram, позже — в приложение: перепечатывать наклейки не нужно. После покупки домена задаётся STICKER_BASE_URL, старые наклейки продолжают работать.",
