"QR-кодты не тапсырыс кодын қолдан жасау не көшіру, Сервистің жұмысына кедергі келтіру, бөгде адамның картасын пайдалану, автоматтандырылған бағдарламалармен кіру, жалған шағым не алдау мақсатындағы қайтару талабы.":"Подделка или копирование QR-кода либо кода заказа, создание помех работе Сервиса, использование чужой карты, вход через автоматизированные программы, ложные жалобы или требования возврата с целью обмана.",
