"Ақша төлем жасалған картаға не Kaspi шотына қайтарылады. Банкке байланысты 1–10 жұмыс күні ішінде түседі. Төлемнің бонуспен жабылған бөлігі бонус болып қайтарылады.":"Деньги возвращаются на карту, с которой была оплата, или на счёт Kaspi. В зависимости от банка они поступают в течение 1–10 рабочих дней. Часть оплаты, покрытая бонусом, возвращается бонусом.",
"Ақша төлем тәсіліңе 1–3 жұмыс күнінде түседі":"Деньги поступят на ваш способ оплаты в течение 1–3 рабочих дней",
"Ақша төленбейді: пакеттен 1 бірлік шегеріледі. Тапсырысты өзің аласың — кассирге «Medeo, тапсырыс нөмірі» және 4 таңбалы кодты айт. Қаласаң, курьер жалдап, жеткенде кодты айтқыз.":"Деньги не списываются: из пакета списывается 1 единица. Заберите заказ сами — назовите кассиру «Medeo, номер заказа» и 4-значный код. При желании отправьте курьера и попросите назвать код.",
"Ақша төленбейді: таңдалған уақытқа пакеттен бір бірлік шегеріледі. Уақытты 2 сағат бұрын тегін ауыстыруға болады.":"Платить не нужно: на выбранное время из пакета списывается одна единица. Перенести время бесплатно можно не позднее чем за 2 часа.",
