"Комиссия деңгейлері: әдепкі — 10%; рейтинг 4,7★ және кемінде 20 пікір болса — 9%; 4,9★ және кемінде 50 пікір — 8%. Деңгейді Сервис автоматты есептейді; Medeo жеке келісіммен басқа комиссия қоя алады (ол басым). Комиссия әр бірлік қолданылған сәтте жазылады: кейін деңгей өзгерсе де, өткен есеп өзгермейді.":"Уровни комиссии: по умолчанию — 10%; при рейтинге 4,7★ и не менее 20 отзывах — 9%; при 4,9★ и не менее 50 отзывах — 8%. Уровень рассчитывает Сервис автоматически; Medeo может установить иную комиссию по индивидуальному соглашению (она имеет приоритет). Комиссия фиксируется в момент использования каждой единицы: если уровень позже изменится, прошлые расчёты не меняются.",
