"Көшірілмеген бірліктердің ақшасы күймейді: олардың құны Medeo бонусы болып автоматты түрде қайтарылады. Бонус 12 ай жарамды, кез келген мекемеде келесі сатып алуда бағадан шегеріледі. Мерзімі өткен бонус жойылады.":"Деньги за неперенесённые единицы не сгорают: их стоимость автоматически возвращается в виде бонуса Medeo. Бонус действует 12 месяцев и вычитается из цены при следующей покупке в любом заведении. Бонус с истёкшим сроком аннулируется.",
"Көшірілмеген бірліктердің құны (бір бірліктің бағасы × қалған бірлік саны) Пайдаланушыға Medeo бонусы ретінде қайтарылады. Бонус 12 ай жарамды және кез келген мекемеде келесі сатып алуда бағадан шегеріледі. Бонус ақшаға айырбасталмайды және басқа адамға берілмейді.":"Стоимость неперенесённых единиц (цена одной единицы × количество оставшихся единиц) возвращается Пользователю в виде бонуса Medeo. Бонус действует 12 месяцев и вычитается из цены при следующей покупке в любом заведении. Бонус не обменивается на деньги и не передаётся другим лицам.",
