"МАҢЫЗДЫ ТӘУЕКЕЛ: 94-V Заңның 12-бабы 2-тармағы дербес деректерді ҚР аумағындағы дерекқорда сақтауды талап етеді. Қазір сервер (GCP europe-west3, Франкфурт) және дерекқор (Neon) ЕО-да. Шешім нұсқалары: (а) ҚР-дағы хостингке көшу (мысалы, ҚР дата-орталықтары не GCP-ның ҚР аймағы болса); (б) ҚР-да негізгі дерекқор + шетелде көшірме; (в) басқа құқықтық негіз. Трансшекаралық беру (16-бап) шарттарын да тексеру.":"ВАЖНЫЙ РИСК: п. 2 статьи 12 Закона 94-V требует хранить персональные данные в базе на территории РК. Сейчас сервер (GCP europe-west3, Франкфурт) и база данных (Neon) находятся в ЕС. Варианты решения: (а) переезд на хостинг в РК; (б) основная база в РК + копия за рубежом; (в) иное правовое основание. Проверить также условия трансграничной передачи (статья 16).",
