"Мекеме 24 сағат ішінде жауап береді. Нәтижесін Telegram-да хабарлаймыз.":"Заведение ответит в течение 24 часов. Результат сообщим в Telegram.",
"Мекеме 24 сағат ішінде жауап береді. Қате расталса, дана пакетке қайтарылады.":"Заведение ответит в течение 24 часов. Если ошибка подтвердится, единица вернётся в пакет.",
"Мекеме «Тек жоспар бойынша» ұсынысқа бос сағат жеңілдігін (5–30%) қоса алады; бос сағат бағасымен жалпы жеңілдік 40%-дан аспайды.":"Заведение может добавить к предложению «Только по плану» скидку в свободные часы (5–30%); общая скидка с ценой свободных часов не превышает 40%.",
"Мекеме атауы":"Название заведения",
"Мекеме атауын жазыңыз":"Укажите название заведения",
"Мекеме бағаны жаңартты. Төлемге дейін тексеріп ал.":"Заведение обновило цену. Проверьте перед оплатой.",
"Мекеме бағаны көтерсе, ұсыныс сатылмаса, карта өшірілсе не банк төлемді өткізбесе (растау сұраса да) — ақша алынбайды, автожаңарту өшеді және Пайдаланушыға хабар барады.":"Если заведение повысило цену, предложение не продаётся, карта удалена или банк не провёл платёж (в том числе запросил подтверждение) — деньги не списываются, автопродление отключается, Пользователь получает уведомление.",
"Мекеме бағаны не құрамды өзгертсе, жаңа шарттар тек жаңа пакеттерге қолданылады. Сатып алынған пакеттің шарттары өзгермейді.":"Если заведение изменит цену или состав, новые условия применяются только к новым пакетам. Условия купленного пакета не меняются.",
"Мекеме белсендіріледі":"Заведение активируется",
"Мекеме беті":"Страница заведения",
"Мекеме бетінде [жұмыс уақыты] көрсетіледі. Пакетті мерзімі ішінде {басқа күні} қолдана аласың.":"На странице заведения указаны [часы работы]. Пакет можно использовать {в другой день} в течение срока.",
"Мекеме болып қосыл":"Подключить заведение",
"Мекеме бос уақытына (апта күндері мен сағаттары) қосымша жеңілдік бере алады. Мұндай пакет тек алдын ала жазылу арқылы, көрсетілген уақыт аралығында қолданылады; кассада QR-мен қолданылмайды. Уақыт аралығы сатып алған сәттегідей сақталады.":"Заведение может дать дополнительную скидку на своё свободное время (дни недели и часы). Такой пакет используется только по предварительной записи в указанный промежуток; на кассе по QR не используется. Промежуток сохраняется таким, каким он был в момент покупки.",
"Мекеме бұл ұсынысты тек алдын ала жоспар бойынша қабылдайды. Пакет бетінде «Қолдану» → күн мен уақытты таңда.":"Заведение принимает это предложение только по предварительной записи. На странице пакета нажмите «Использовать» и выберите дату и время.",
"Мекеме бұл ұсынысты тек мына филиалдарда қабылдайды. Бірлік жұмсалған жоқ.":"Заведение принимает это предложение только в этих филиалах. Единица не списана.",
"Мекеме бұл ұсынысты қазір сатпайды. Басқа ұсыныстарды қарап көр.":"Заведение сейчас не продаёт это предложение. Посмотрите другие предложения.",
"Мекеме бөлімі":"Раздел заведения",
"Мекеме бөлімі · сынақ (C2)":"Раздел заведения · тест (C2)",
"Мекеме дәл осы уақытқа дайындап қояды. 2 сағат қалғанға дейін тегін ауыстыруға не бас тартуға болады, кейін бірлік жұмсалады.":"Заведение подготовит заказ точно к этому времени. Изменить или отменить бесплатно можно не позднее чем за 2 часа, позже единица спишется.",
"Мекеме жабылса, қызмет көрсетуден бас тартса не ұсыныс шарттарын орындамаса, пайдаланылмаған бірліктердің құны қайтарылады.":"Если заведение закрылось, отказалось оказывать услугу или не выполнило условия предложения, стоимость неиспользованных единиц возвращается.",
"Мекеме жабылса, қызметтен бас тартса не ұсыныс шарттарын орындамаса, пайдаланылмаған бірліктердің құны толық қайтарылады.":"Если заведение закрылось, отказалось оказывать услугу или не выполнило условия предложения, стоимость неиспользованных единиц возвращается полностью.",
"Мекеме жабық болса не орын бермесе («Мекеме қабылдамады» шағымы), пакет мерзімі бірден 7 күнге ұзартылады (бір пакетке 2 ретке дейін).":"Если заведение закрыто или не даёт места (жалоба «Заведение не приняло»), срок пакета сразу продлевается на 7 дней (до 2 раз на один пакет).",
