"Мекеме иесі жіберген 6 таңбалы код. Ол қосымшада «Кассир шақыру» арқылы жасалады.":"6-значный код от владельца заведения. Он создаётся в приложении через «Пригласить кассира».",
"Мекеме иесі растағанша күтіңіз. Растау кезінде Telegram арқылы хабарлаймыз.":"Дождитесь подтверждения владельца заведения. Мы сообщим в Telegram.",
"Мекеме иесі қызметкерлерді Сервиске шақырады және олардың рұқсатын басқарады. Қызметкерлердің әрекеті үшін Мекеме жауап береді.":"Владелец Заведения приглашает сотрудников в Сервис и управляет их доступом. За действия сотрудников отвечает Заведение.",
"Мекеме иесінің шақыру кодымен":"По коду приглашения от владельца заведения",
"Мекеме картасы":"Карточка заведения",
"Мекеме клиент шағымына [24] сағат ішінде жауап береді. Қате шегеру расталса, бірлік клиентке қайтарылады. Мекеме кінәсінен ақша қайтарылса, сома Мекеменің үлесінен ұсталады.":"Заведение отвечает на жалобу клиента в течение [24] часов. Если ошибочное списание подтвердится, единица возвращается клиенту. Если деньги возвращаются по вине Заведения, сумма удерживается из доли Заведения.",
"Мекеме клиенттің деректерін (аты, тапсырыс коды) тек қызмет көрсету үшін қолданады және жарнамаға не үшінші тұлғаға бермейді. Мекеменің тіркеу құжаттары жабық сақталады және тек тексеру үшін қолданылады.":"Заведение использует данные клиента (имя, код заказа) только для оказания услуги и не передаёт их для рекламы или третьим лицам. Регистрационные документы Заведения хранятся закрыто и используются только для проверки.",
"Мекеме кінәлі болса.":"Если виновато заведение.",
"Мекеме мен пакетті таңда, бір рет төле.":"Выберите заведение и пакет, оплатите один раз.",
"Мекеме пайдасына":"В пользу заведения",
"Мекеме профилі":"Профиль заведения",
"Мекеме рұқсат берсе, мерзімді ұзартуға болады: бір рет тегін 7 күнге, ақылы 14 күнге (1 000 ₸) не 30 күнге (2 000 ₸). Бір пакетті жалпы 60 күнге дейін ұзартуға болады (мекеме ескі бағамен шексіз қызмет етуге міндетті емес). Ағымдағы баға мен қалған шек Сервисте көрсетіледі.":"Если заведение разрешает, срок можно продлить: один раз бесплатно на 7 дней, платно на 14 дней (1 000 ₸) или на 30 дней (2 000 ₸). Один пакет можно продлить в сумме до 60 дней (заведение не обязано бесконечно обслуживать по старой цене). Актуальная цена и оставшийся лимит указаны в Сервисе.",
"Мекеме сатуды уақытша тоқтата алады: жаңа пакет сатылмайды, ал бұрын сатылған пакеттер бойынша қызмет мерзімі біткенше көрсетіледі не клиентке ақша қайтарылады.":"Заведение может временно приостановить продажи: новые пакеты не продаются, а ранее проданные обслуживаются до конца срока, либо клиенту возвращаются деньги.",
"Мекеме себепті көріп, түзетіп қайта жібере алады.":"Заведение увидит причину, исправит и отправит заново.",
