"Мекеме ұсыну":"Предложить заведение",
"Мекеме ұсыныстың құрамын, бағасын, бірлік санын, мерзімін және шектеулерін өзі белгілейді. Ұсыныстар жарияланбас бұрын Medeo тексеруінен өтуі мүмкін.":"Заведение само определяет состав, цену, количество единиц, срок и ограничения предложения. Перед публикацией предложения могут проходить проверку Medeo.",
"Мекеме өтімділігі":"Ликвидность заведений",
"Мекеме өтінімдері":"Заявки заведений",
"Мекеме өтінімді жіберіп, «Қолдану шарттарымен және тарифпен келісемін» белгісін қойғанда осы шартты қабылдайды. Шарт өтінім мақұлданған сәттен күшіне енеді.":"Заведение принимает настоящий договор, отправляя заявку и отмечая «Согласен с условиями использования и тарифом». Договор вступает в силу с момента одобрения заявки.",
"Мекеме — Сервисте ұсыныс жариялаған және қызметті тікелей көрсететін кәсіпкер не ұйым.":"Заведение — предприниматель или организация, разместившие предложение в Сервисе и непосредственно оказывающие услугу.",
"Мекемеге ақша әр қолданған сәтте бірден өтеді. Бұл бет тек қорытынды есеп: қосымша аударым жасаудың қажеті жоқ.":"Деньги поступают заведению сразу при каждом использовании. Эта страница — только итоговый отчёт: дополнительные переводы не нужны.",
"Мекемеге барып, кассирге «Medeo бойынша» деп айтып, QR-ды сканерле.":"Подойдите в заведение, скажите кассиру «по Medeo» и отсканируйте QR.",
