"Мекемеге хабарлама":"Сообщение заведению",
"Мекемеге хабарлама жіберілді. Енді ол ұсыныс құра алады; алғашқы ұсынысы модерацияға түседі.":"Заведению отправлено уведомление. Теперь оно может создавать предложения; первое предложение уйдёт на модерацию.",
"Мекемеге өту":"К заведению",
"Мекемеге — тапсырыс пен қолдану үшін тек атың және тапсырыс коды; телефон мен карта деректері берілмейді.":"Заведению — только ваше имя и код заказа для заказа и использования; телефон и данные карты не передаются.",
"Мекемеде QR сканерлеп төлесең, осында көрінеді":"Оплатите в заведении, отсканировав QR, — и использование появится здесь",
