"Мекемеде «Қолдану» батырмасын бас да, кассадағы QR-ды сканерле":"В заведении нажмите «Использовать» и отсканируйте QR на кассе",
"Мекемеде навигациядағы [Сканер] батырмасын басып, кассирдің QR-ын сканерле. Бірлік пакеттен {өзі шегеріледі}.":"В заведении нажмите кнопку [Сканер] в навигации и отсканируйте QR кассира. Единица {спишется из пакета сама}.",
