"Мерзім біткен соң 3 күн ішінде пакетті қайта алсаң, қалған бірліктер жаңа пакетке көшеді.":"Если в течение 3 дней после окончания срока снова купить пакет, оставшиеся единицы перейдут в новый пакет.",
"Мерзім біткен соң 3 күн ішінде сол ұсыныстың пакетін қайта алсаң, пайдаланылмаған бірліктер жаңа пакетке көшеді. Көшкен бірліктер ескі пакетте төленген бағасымен есептеледі.":"Если в течение 3 дней после окончания срока купить пакет того же предложения, неиспользованные единицы перейдут в новый пакет. Перенесённые единицы учитываются по цене, оплаченной в старом пакете.",
