"Мерзімі өтіп, қолданылмаған бірліктердің ақшасы Мекемеге берілмейді: ол клиентке Medeo бонусы болып қайтарылады. Клиент бонусты кез келген мекемеде, соның ішінде осы Мекемеде жұмсай алады.":"Деньги за неиспользованные единицы с истёкшим сроком Заведению не передаются: они возвращаются клиенту в виде бонуса Medeo. Клиент может потратить бонус в любом заведении, в том числе в этом.",
