"Осы құжат Қазақстан Республикасы Азаматтық кодексінің 395-бабына сәйкес жария оферта болып табылады. {0} (БСН {1}, бұдан әрі — «Medeo») кез келген жеке тұлғаға (бұдан әрі — «Пайдаланушы») Medeo сервисі арқылы мекемелердің пакеттерін сатып алуды ұсынады.":"Настоящий документ является публичной офертой в соответствии со статьёй 395 Гражданского кодекса Республики Казахстан. {0} (БИН {1}, далее — «Medeo») предлагает любому физическому лицу (далее — «Пользователь») приобрести пакеты заведений через сервис Medeo.",
