"Пайдаланушы белсенді пакет бетінде автожаңартуды өзі қосады және кез келген уақытта өшіре алады. Қосылған сәт пен таңдалған карта сақталады. Бұл — тұрақты (қайталанатын) төлемге келісім.":"Пользователь сам включает автопродление на странице активного пакета и может отключить его в любой момент. Время включения и выбранная карта сохраняются. Это согласие на регулярные (повторяющиеся) платежи.",
