"Пакет ақшасы бірлік қолданылған сәтте бөлінеді: бір бірліктің бағасынан Medeo комиссиясы ұсталып, қалғаны Мекемеге тиесілі болады. Мекеме тек нақты көрсеткен қызметі үшін ақша алады.":"Деньги за пакет распределяются в момент использования единицы: из цены одной единицы удерживается комиссия Medeo, остальное причитается Заведению. Заведение получает деньги только за фактически оказанную услугу.",
