"Пакет біткенде (бірлігі таусылып, жазылған соңғы келу орындалса не мерзімі өтсе) сол ұсыныстың сол көлемі сақталған картадан қайта алынады — әр пакет үшін бір рет; пайдаланылмаған бірліктер жаңа пакетке көшеді. Жаңа пакет те автожаңарумен жалғасады: Пайдаланушы өшіргенше әр пакет біткен сайын қайталанады. Әр төлем туралы бот хабарлайды.":"Когда пакет заканчивается (закончились единицы и состоялся последний записанный визит, либо истёк срок), тот же объём того же предложения снова оплачивается сохранённой картой — один раз на каждый пакет; неиспользованные единицы переходят в новый пакет. Новый пакет тоже продлевается автоматически: пока Пользователь не отключит, оплата повторяется каждый раз, когда пакет заканчивается. О каждом платеже сообщает бот.",
