"Пакет жеңілдігі кемінде 10%, ең көбі 30% (Medeo тарифі бойынша) болуы тиіс: тым арзан пакетте клиентке қызмет көрсету Мекемеге тиімсіз болады.":"Скидка на пакет должна быть не менее 10% и не более 30% (по тарифу Medeo): обслуживать клиента по слишком дешёвому пакету Заведению невыгодно.",
