"Пакеттен бірде-бір бірлік жұмсалмаған — ақша толық қайтарылады, пакет жабылады. Картадан төленген бөлігі картаңа, Squirrel бонусымен төленген бөлігі бонусыңа оралады.":"Из пакета не использовано ни одной единицы — деньги вернутся полностью, пакет закроется. Часть, оплаченная картой, вернётся на карту, часть, оплаченная бонусом Squirrel, — на бонус.",
"Пакеттен бірде-бір бірлік қолданылмаса, сатып алғаннан кейін [14] күн ішінде төленген соманы толық қайтаруды сұрауға болады. Пакет бетіндегі «Ақшаны қайтару» батырмасы арқылы бірден жүзеге асады.":"Если из пакета не использовано ни одной единицы, в течение [14] дней после покупки можно запросить полный возврат оплаченной суммы. Возврат выполняется сразу кнопкой «Вернуть деньги» на странице пакета.",
