"Пакетті басқа адамға сыйлауға болады. Алушы 7 күн ішінде қабылдамаса не сатып алушы сыйлықты болдырмаса, пакет сатып алушыға қайтады. Сыйлықтың мерзімі алушы қабылдаған сәттен басталады.":"Пакет можно подарить другому человеку. Если получатель не примет подарок в течение 7 дней или покупатель отменит подарок, пакет вернётся покупателю. Срок подарка начинается с момента, когда его принял получатель.",
