"Пакеттің":"Срок",
"Пакеттің мерзімі сатып алған сәттен басталады және ұсыныста көрсетілген күн санына (әдетте 30 күн) созылады.":"Срок пакета начинается с момента покупки и длится указанное в предложении количество дней (обычно 30 дней).",
"Пакеттің мерзімі өткен соң 3 күн күтеміз. Клиент осы уақытта қайта алса, қалған бірліктер жаңа пакетке көшеді. Алмаса, қалдық сомасы клиентке Medeo бонусы болып қайтады. Мекемеге ақша тек көрсеткен қызмет үшін түседі.":"После окончания срока пакета ждём 3 дня. Если клиент за это время купит снова, оставшиеся единицы перейдут в новый пакет. Если нет — сумма остатка вернётся клиенту бонусом Medeo. Заведение получает деньги только за оказанные услуги.",
